-- Seed Parent Sheep (Eksternal, no cage reference)
INSERT INTO livestock.sheep (id_sheep, sheep_code, sheep_name, gender, date_of_birth, status, origin, id_cage, id_type, created_by) VALUES 
('77777777-7777-7777-7777-777777777799', 'DF2 TT', 'Bapak DF2 TT', 'jantan', '2021-01-01', 'eksternal', 'lokal', NULL, '22222222-2222-2222-2222-222222222203', '11111111-1111-1111-1111-111111111101')
ON CONFLICT (sheep_code) DO NOTHING;

DO $$
DECLARE
    i INT;
    gender_val VARCHAR(10);
    uuid_str VARCHAR(50);
    code_str VARCHAR(10);
BEGIN
    FOR i IN 0..56 LOOP
        IF i = 1 THEN
            gender_val := 'jantan';
        ELSIF i = 0 THEN
            gender_val := 'betina';
        ELSIF i % 2 = 0 THEN
            gender_val := 'jantan';
        ELSE
            gender_val := 'betina';
        END IF;
        
        uuid_str := '77777777-7777-7777-7777-7777777777' || to_char(i, 'FM00');
        code_str := 'NN' || to_char(i, 'FM00');
        
        INSERT INTO livestock.sheep (id_sheep, sheep_code, sheep_name, gender, date_of_birth, status, origin, id_cage, id_type, created_by)
        VALUES (uuid_str::UUID, code_str, 'Domba ' || code_str, gender_val::livestock.gender_enum, '2021-01-01', 'eksternal', 'lokal', NULL, '22222222-2222-2222-2222-222222222201', '11111111-1111-1111-1111-111111111101')
        ON CONFLICT (sheep_code) DO NOTHING;
    END LOOP;
END $$;

